// Um e-mail por inadimplente QUE TEM e-mail. A 'mensagem' (régua) já vem pronta do app.
const body = $json.body || $json;
const lista = body.inadimplentes || [];
const out = [];
for (const i of lista) {
  if (!i.email) continue; // sem e-mail → não envia (entra no resumo do gestor)
  out.push({
    json: {
      to: i.email,
      assunto: `Indeba — aviso de pagamento em aberto (${i.cliente})`,
      corpo: i.mensagem,
    },
  });
}
return out;

// Resumo do disparo para o gestor: quem recebeu, quem ficou sem e-mail, total.
const body = $json.body || $json;
const lista = body.inadimplentes || [];
const comEmail = lista.filter((i) => i.email);
const semEmail = lista.filter((i) => !i.email);
const linha = (i) => `• ${i.cliente} — R$ ${i.valorDevido} (${i.diasAtraso} dias, ${i.severidade})`;
const corpo = [
  `Disparo de cobrança concluído.`,
  ``,
  `Clientes cobrados por e-mail: ${comEmail.length} de ${lista.length}`,
  `Total em aberto: R$ ${body.totalDevido}`,
  ``,
  `— Enviados —`,
  ...comEmail.map(linha),
  ...(semEmail.length ? [``, `— SEM E-MAIL (não enviados, cadastre o e-mail) —`, ...semEmail.map(linha)] : []),
].join('\n');
return [{ json: { to: body.gestorEmail, assunto: `Resumo de cobrança Indeba — ${comEmail.length}/${lista.length} enviados`, corpo } }];
